    api.func("screenSetSelection", .{ .name = "setSelection" }),
    api.func("screenViewportTop", .{ .name = "viewportTop" }),
    api.func("screenScrollbar", .{ .name = "scrollbar" }),
    api.func("screenFormat", .{ .name = "format" }),
