const kitty_images_group = KittyImages.define(&.{
    api.func("newKittyImages", .{ .role = .{ .constructor = .{ .type = KittyImages.typeRef() } } }),
    api.func("freeKittyImages", .{ .role = .{ .destructor = KittyImages.typeRef() } }),
